drop table if exists public.shipment_financial_ledger cascade; drop table if exists public.delivery_assignments cascade; create table public.shipment_financial_ledger (id uuid primary key default gen_random_uuid(), shipment_id text not null references public.shipments(id) on delete cascade, entry_type text not null check (entry_type in ('charge','payment','refund','adjustment')), amount numeric(14,2) not null, currency text not null default 'USD', reference text, note text, recorded_by uuid references public.staff(id), created_at timestamptz not null default now()); create index idx_shipment_financial_ledger_shipment on public.shipment_financial_ledger(shipment_id,created_at desc); alter table public.shipment_financial_ledger enable row level security; create policy shipment_financial_ledger_staff_select on public.shipment_financial_ledger for select to authenticated using (exists(select 1 from public.staff s where s.id=auth.uid() and coalesce(s.is_active,s.active)=true)); create policy shipment_financial_ledger_staff_insert on public.shipment_financial_ledger for insert to authenticated with check (exists(select 1 from public.staff s where s.id=auth.uid() and coalesce(s.is_active,s.active)=true)); create table public.delivery_assignments (id uuid primary key default gen_random_uuid(), shipment_id text not null references public.shipments(id) on delete cascade, assigned_staff_id uuid references public.staff(id), status text not null default 'assigned' check(status in ('assigned','accepted','picked_up','out_for_delivery','delivered','failed','cancelled')), pickup_at timestamptz, delivered_at timestamptz, proof_id uuid references public.delivery_proofs(id), note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index idx_delivery_assignments_shipment on public.delivery_assignments(shipment_id,created_at desc); create index idx_delivery_assignments_staff on public.delivery_assignments(assigned_staff_id,status); alter table public.delivery_assignments enable row level security; create policy delivery_assignments_staff_select on public.delivery_assignments for select to authenticated using (exists(select 1 from public.staff s where s.id=auth.uid() and coalesce(s.is_active,s.active)=true)); create policy delivery_assignments_staff_write on public.delivery_assignments for all to authenticated using (exists(select 1 from public.staff s where s.id=auth.uid() and coalesce(s.is_active,s.active)=true)) with check (exists(select 1 from public.staff s where s.id=auth.uid() and coalesce(s.is_active,s.active)=true));;
